class Student:
    def __init__(self, name, mark):
        self.name = name
        self.mark = mark

    def is_pass(self):
        return self.mark >= 40

    def display(self):
        status = "Pass" if self.is_pass() else "Fail"
        print("Name: %s | Mark: %d | Result: %s" % (self.name, self.mark, status))

try:
    students = []
    with open("students.txt", "r") as file:
        for line in file:
            line = line.strip()
            if line:
                name, mark_str = line.split(",")
                students.append(Student(name, int(mark_str)))

    print("===== STUDENT REPORT =====\n")
    passed_count = 0
    for s in students:
        s.display()
        if s.is_pass():
            passed_count += 1

    print("\nTotal Students: %d" % len(students))
    print("Passed Students: %d" % passed_count)

except FileNotFoundError:
    print("Student file not found")
